package com.tekwatt.ocpp.service;import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.stereotype.Service;import org.springframework.web.socket.*;@Service public class ConnectionRegistry{private final Map<String,WebSocketSession> sessions=new ConcurrentHashMap<>();private final Map<String,Instant> connectedAt=new ConcurrentHashMap<>();public void add(String station,WebSocketSession s){WebSocketSession old=sessions.put(station,s);connectedAt.put(station,Instant.now());if(old!=null&&old.isOpen())try{old.close();}catch(Exception ignored){}}public void remove(String station,WebSocketSession s){sessions.remove(station,s);connectedAt.remove(station);}public List<ConnectionInfo>all(){return sessions.entrySet().stream().map(e->new ConnectionInfo(e.getKey(),e.getValue().isOpen(),connectedAt.get(e.getKey()),e.getValue().getAcceptedProtocol())).toList();}public Optional<ConnectionInfo>get(String station){WebSocketSession s=sessions.get(station);return s==null?Optional.empty():Optional.of(new ConnectionInfo(station,s.isOpen(),connectedAt.get(station),s.getAcceptedProtocol()));}public void send(String station,String text)throws Exception{WebSocketSession s=sessions.get(station);if(s==null||!s.isOpen())throw new IllegalStateException("Charger is not connected");s.sendMessage(new TextMessage(text));}public String protocol(String station){WebSocketSession s=sessions.get(station);if(s==null||!s.isOpen())throw new IllegalStateException("Charger is not connected");return s.getAcceptedProtocol();}public record ConnectionInfo(String stationId,boolean connected,Instant connectedAt,String protocol){}}
